mapper.select:
SELECT id, workspace_id, provision_ceased_at
FROM person
WHERE workspace_id = #{workspaceId} AND id = #{id}

mapper.insert:
INSERT INTO company_share (company_id, workspace_id, granted_by, can_edit)
SELECT c.id, #{targetWorkspaceId}, #{grantedBy}, #{canEdit}
FROM company c
WHERE c.id = #{id} AND c.workspace_id = #{workspaceId}
  AND #{targetWorkspaceId} IN

    #{allowedWorkspaceId}

ON DUPLICATE KEY UPDATE can_edit = #{canEdit}, granted_by = #{grantedBy}

INSERT INTO person_share (person_id, workspace_id, granted_by, can_edit)
SELECT p.id, #{targetWorkspaceId}, #{grantedBy}, #{canEdit}
FROM person p
WHERE p.id = #{id} AND p.workspace_id = #{workspaceId}
  AND p.provision_ceased_at IS NULL
  AND #{targetWorkspaceId} IN

    #{allowedWorkspaceId}

ON DUPLICATE KEY UPDATE can_edit = #{canEdit}, granted_by = #{grantedBy}

INSERT INTO pipeline_share (pipeline_id, workspace_id, granted_by, can_edit)
SELECT pl.id, #{targetWorkspaceId}, #{grantedBy}, #{canEdit}
FROM pipeline pl
WHERE pl.id = #{id} AND pl.workspace_id = #{workspaceId}
  AND #{targetWorkspaceId} IN

    #{allowedWorkspaceId}

ON DUPLICATE KEY UPDATE can_edit = #{canEdit}, granted_by = #{grantedBy}

mapper.delete:
DELETE s FROM company_share s
JOIN company c ON c.id = s.company_id AND c.workspace_id = #{workspaceId}
WHERE s.company_id = #{id} AND s.workspace_id = #{targetWorkspaceId}

DELETE s FROM person_share s
JOIN person p ON p.id = s.person_id AND p.workspace_id = #{workspaceId}
WHERE s.person_id = #{id} AND s.workspace_id = #{targetWorkspaceId}

DELETE s FROM person_share s
JOIN person p ON p.id = s.person_id AND p.workspace_id = #{workspaceId}
WHERE s.person_id = #{id}

DELETE s FROM pipeline_share s
JOIN pipeline pl ON pl.id = s.pipeline_id AND pl.workspace_id = #{workspaceId}
WHERE s.pipeline_id = #{id} AND s.workspace_id = #{targetWorkspaceId}

mapper.select:
SELECT s.workspace_id AS workspaceId, s.can_edit AS canEdit, s.created_at AS createdAt
FROM company_share s
JOIN company c ON c.id = s.company_id AND c.workspace_id = #{workspaceId}
WHERE s.company_id = #{id}
ORDER BY s.workspace_id

SELECT s.workspace_id AS workspaceId, s.can_edit AS canEdit, s.created_at AS createdAt
FROM person_share s
JOIN person p ON p.id = s.person_id AND p.workspace_id = #{workspaceId}
WHERE s.person_id = #{id}
ORDER BY s.workspace_id

SELECT s.workspace_id AS workspaceId, s.can_edit AS canEdit, s.created_at AS createdAt
FROM pipeline_share s
JOIN pipeline pl ON pl.id = s.pipeline_id AND pl.workspace_id = #{workspaceId}
WHERE s.pipeline_id = #{id}
ORDER BY s.workspace_id
